*{box-sizing:border-box} :root{--ink:#071322;--paper:#eff6ee;--cyan:#69f6e2;--orange:#ffbd78;--muted:rgba(233,244,238,.56)} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:'Space Grotesk',sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#0b2132}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(4,13,24,.25) 0%,transparent 35%,rgba(4,12,22,.12) 65%,rgba(3,10,19,.49) 100%),radial-gradient(ellipse at 50% 50%,transparent 42%,rgba(3,10,19,.29) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(227,242,235,.14);font:500 10px 'DM Mono',monospace;letter-spacing:.13em}.brand{color:#f3f5e9;text-decoration:none;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:.12em}.brand-mark{color:var(--cyan);font-size:20px;vertical-align:-2px;margin-right:8px}.brand-divider{color:rgba(255,255,255,.3);margin:0 9px}.brand-sub{font:400 9px 'DM Mono',monospace;color:rgba(239,246,238,.55);letter-spacing:.19em}.run-label{color:rgba(245,248,236,.7)}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#aaf3a1;box-shadow:0 0 11px #aaf3a1;margin-right:8px}.run-divider{padding:0 9px;color:var(--cyan)}.sound-button{background:none;border:0;color:rgba(239,246,238,.75);font:500 12px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}.sound-button span{font-size:9px;margin-left:6px}.hud{position:absolute;z-index:2;top:96px;left:5.2%;right:5.2%;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.eyebrow,.shard-label{font:500 9px 'DM Mono',monospace;color:rgba(236,245,232,.62);letter-spacing:.18em}.distance{display:flex;align-items:center;margin-top:8px;font-size:37px;line-height:.9;letter-spacing:-.06em;font-weight:600}.distance small{font:400 9px 'DM Mono',monospace;color:rgba(236,245,232,.58);letter-spacing:.13em;line-height:1.55;margin-left:9px}.hud-center{width:min(350px,38vw);margin-top:5px}.wake-title{font:500 10px 'DM Mono',monospace;letter-spacing:.15em}.wake-title>span{color:var(--cyan);font-size:15px;margin-right:7px}.wake-title small{float:right;color:rgba(239,246,238,.55);font-size:8px}.wake-track{position:relative;margin-top:9px;height:3px;background:rgba(235,246,238,.2);overflow:hidden}.wake-fill{width:0;height:100%;background:var(--cyan);box-shadow:0 0 12px var(--cyan);transition:width .12s}.wake-glint{position:absolute;right:0;top:-2px;width:1px;height:7px;background:#fff}.wake-hint{margin-top:7px;color:rgba(235,246,238,.49);font:400 8px 'DM Mono',monospace;letter-spacing:.12em}.hud-right{text-align:right}.shard-count{font-size:30px;font-weight:600;line-height:1;margin-top:7px}.shard-icon{font-size:15px;color:var(--orange);margin-left:7px;text-shadow:0 0 12px var(--orange)}.bottomline{position:absolute;z-index:2;bottom:25px;left:5.2%;right:5.2%;display:flex;justify-content:space-between;color:rgba(235,244,235,.47);font:400 8px 'DM Mono',monospace;letter-spacing:.15em;pointer-events:none}.bottomline b{color:var(--cyan);padding:0 5px}.overlay{position:absolute;z-index:4;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(5,16,29,.28);backdrop-filter:blur(2px);transition:opacity .45s,visibility .45s}.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card,.result-card{width:min(570px,75vw);padding:38px 48px 31px;background:linear-gradient(135deg,rgba(11,28,44,.91),rgba(9,24,39,.84));border:1px solid rgba(215,237,226,.23);box-shadow:0 24px 80px rgba(0,0,0,.24);position:relative}.intro-card:before,.result-card:before{content:'';position:absolute;top:-1px;left:48px;width:73px;height:2px;background:var(--cyan);box-shadow:0 0 15px var(--cyan)}.kicker{display:flex;align-items:center;gap:12px;color:var(--cyan);font:500 9px 'DM Mono',monospace;letter-spacing:.2em}.kicker-line{width:23px;height:1px;background:rgba(105,246,226,.57)}.title-wrap{position:relative}.title-wrap h1{font-size:clamp(43px,6.1vw,69px);line-height:.88;letter-spacing:-.075em;margin:19px 0 17px;font-weight:600}.title-wrap h1 em{font-style:normal;color:var(--orange)}.title-star{position:absolute;right:12px;top:13px;font-size:43px;color:var(--cyan);opacity:.85}.intro-copy{max-width:390px;color:rgba(237,245,237,.73);font-size:12px;line-height:1.65;margin:0 0 21px}.mission-row{display:flex;gap:13px;align-items:center;padding:11px 0;border-top:1px solid rgba(220,239,229,.13)}.mission-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid rgba(105,246,226,.33);color:var(--cyan);font-size:20px;flex:none}.challenge-row .mission-icon{color:var(--orange);border-color:rgba(255,189,120,.35)}.mission-row b,.mission-row small{display:block}.mission-row b{font:500 9px 'DM Mono',monospace;letter-spacing:.12em;color:#e8f4eb}.mission-row small{font-size:10px;color:rgba(237,245,237,.55);margin-top:4px}.start-button{margin-top:21px;width:100%;height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 19px;background:var(--cyan);border:0;color:#09202c;font:700 11px 'DM Mono',monospace;letter-spacing:.17em;cursor:pointer;transition:background .2s,transform .2s}.start-button:hover{background:#a0ffeb;transform:translateY(-2px)}.start-button span{font-size:18px}.controls-note{margin-top:15px;color:rgba(233,242,235,.43);text-align:center;font:400 8px 'DM Mono',monospace;letter-spacing:.09em}.controls-note span{color:rgba(235,247,239,.8);border:1px solid rgba(230,241,233,.26);padding:3px 4px}.controls-note i{font-style:normal;padding:0 4px}.intro-side{position:absolute;right:5.5%;top:44%;display:flex;align-items:center;gap:10px;writing-mode:vertical-rl;font:400 8px 'DM Mono',monospace;letter-spacing:.22em;color:rgba(240,246,235,.48)}.side-number{color:var(--cyan)}.side-rule{width:1px;height:47px;background:rgba(226,240,229,.35)}.result-card{text-align:center}.result-card .kicker{justify-content:center}.result-card h2{font-size:clamp(34px,5vw,55px);letter-spacing:-.06em;margin:19px 0 8px}.result-card p{color:rgba(237,245,237,.68);font-size:13px}.report{display:flex;justify-content:center;gap:0;margin:27px 0 12px;border-top:1px solid rgba(220,239,229,.14);border-bottom:1px solid rgba(220,239,229,.14);padding:17px 0}.report div{min-width:31%;display:flex;flex-direction:column;gap:6px}.report div+div{border-left:1px solid rgba(220,239,229,.14)}.report small{color:rgba(237,245,237,.5);font:8px 'DM Mono',monospace;letter-spacing:.13em}.report b{font-size:19px}.toast{position:absolute;z-index:3;top:28%;left:50%;transform:translate(-50%,-10px);opacity:0;color:var(--cyan);font:500 10px 'DM Mono',monospace;letter-spacing:.18em;text-shadow:0 0 16px rgba(105,246,226,.7);transition:all .3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none}
@media(max-width:700px){.topbar{height:60px;padding:0 18px}.brand{font-size:12px}.brand-sub{font-size:7px}.run-label{font-size:8px}.sound-button span{display:none}.hud{top:76px;left:19px;right:19px}.hud-center{width:37vw}.wake-hint{font-size:6px;line-height:1.4}.wake-title{font-size:8px}.wake-title small{float:none;display:block;margin:4px 0 0 20px;font-size:7px}.distance{font-size:30px}.shard-count{font-size:26px}.eyebrow,.shard-label{font-size:7px}.bottomline{left:18px;right:18px;bottom:12px;font-size:6px}.bottomline span:first-child{max-width:45%}.intro-card,.result-card{width:min(520px,calc(100% - 34px));padding:29px 25px 24px}.title-wrap h1{font-size:clamp(45px,12vw,65px)}.title-star{right:1px;font-size:30px}.intro-copy{font-size:11px}.mission-row b{font-size:8px}.mission-row small{font-size:9px}.intro-side{display:none}.controls-note{font-size:7px}.mobile-controls{display:flex;position:absolute;z-index:3;bottom:41px;left:18px;right:18px;align-items:end;justify-content:space-between;pointer-events:none}.mobile-controls button{pointer-events:auto;touch-action:none}.dpad{display:flex;align-items:center;gap:4px}.dpad button,.vertical-pad button{height:43px;min-width:43px;border:1px solid rgba(231,244,235,.35);background:rgba(9,28,43,.48);backdrop-filter:blur(5px);color:rgba(239,248,238,.9);font-size:23px;border-radius:3px}.vertical-pad{display:flex;flex-direction:column;gap:4px}.vertical-pad button{height:19px;font-size:12px;line-height:12px}.boost-button{width:75px;height:60px;border:1px solid rgba(105,246,226,.55);background:rgba(7,29,42,.72);color:var(--cyan);font:500 8px 'DM Mono',monospace;letter-spacing:.12em;border-radius:50%;box-shadow:inset 0 0 18px rgba(105,246,226,.08)}.boost-button span{display:block;font-size:19px;margin-bottom:3px}.mobile-controls[hidden]{display:none}.overlay{background:rgba(5,16,29,.45)}}
@media(max-height:700px){.intro-card{padding-top:24px;padding-bottom:19px}.title-wrap h1{font-size:clamp(41px,5.5vw,58px);margin:13px 0}.intro-copy{margin-bottom:13px}.mission-row{padding:8px 0}.start-button{margin-top:14px;height:43px}.controls-note{margin-top:11px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const intro = document.getElementById('intro');
  const result = document.getElementById('result');
  const hud = document.getElementById('hud');
  const mobileControls = document.getElementById('mobileControls');
  const wakeFill = document.getElementById('wakeFill');
  const wakeState = document.getElementById('wakeState');
  const gateCount = document.getElementById('gateCount');
  const shardCount = document.getElementById('shardCount');
  const toast = document.getElementById('toast');
  const keys = new Set();
  const touch = { left:false,right:false,up:false,down:false,boost:false };
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  let W=innerWidth,H=innerHeight,DPR=1,last=0,mode='menu',time=0,toastTimer=0;
  let player,objects,particles,score,shards,misses,streak,bestStreak,charge,burst,runTime,shake=0;
  let soundOn=false,audio;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(a,b)=>a+Math.random()*(b-a);
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}
  addEventListener('resize',resize);resize();
  function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
  function current(){return {x:Math.sin(time*.00039)*.36+Math.sin(time*.00017)*.12,y:Math.sin(time*.00027+1.6)*.24}}
  function reset(){
    time=0;runTime=0;score=0;shards=0;misses=0;streak=0;bestStreak=0;charge=0;burst=0;shake=0;
    player={x:0,y:.47,vx:0,vy:0,tilt:0};objects=[];particles=[];
    const gatePos=[[-.42,.28],[.28,-.26],[.55,.28],[-.18,-.34],[-.58,.22],[.2,.36],[.48,-.25],[-.15,.06]];
    gatePos.forEach((p,i)=>objects.push({type:'gate',x:p[0],y:p[1],z:9+i*12.7,id:i+1,done:false}));
    const shardPos=[[-.12,.06],[.44,-.06],[-.42,-.13],[.12,.28],[-.05,-.3]];
    shardPos.forEach((p,i)=>objects.push({type:'shard',x:p[0],y:p[1],z:15+i*15.1,id:i,done:false}));
    [[.52,.15,26],[-.58,-.22,47],[.04,.02,69],[-.49,.12,87],[.55,-.2,102]].forEach((p,i)=>objects.push({type:'mine',x:p[0],y:p[1],z:p[2],id:i,done:false}));
    gateCount.textContent='00';shardCount.textContent='0';wakeFill.style.width='0%';wakeState.textContent='FIND THE CURRENT';
  }
  function start(){reset();mode='playing';intro.classList.add('hidden');result.classList.add('hidden');hud.style.opacity='1';mobileControls.hidden=false;notify('FOLLOW THE CYAN WAKE')}
  function end(won){mode=won?'won':'lost';result.classList.remove('hidden');document.getElementById('resultTitle').textContent=won?'EXPANSE CONQUERED':'FLIGHT ENDED';document.getElementById('resultCopy').textContent=won?(shards>=5?'Five shards. Eight gates. The skyway is yours.':'You found the way through. Bring back all five shards next run.'):'The storm swallowed your line. The sky will be there tomorrow.';document.getElementById('resultGates').textContent=String(score).padStart(2,'0')+' / 08';document.getElementById('resultShards').textContent=shards+' / 5';document.getElementById('resultStreak').textContent=bestStreak+' gates';mobileControls.hidden=true;hud.style.opacity='.45'}
  document.getElementById('startButton').addEventListener('click',start);document.getElementById('againButton').addEventListener('click',start);
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Spacebar'].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if((e.key==='Enter'||e.key===' ')&&(mode==='menu'||mode==='won'||mode==='lost')){if(mode==='menu')start();else start()}});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir;const on=e=>{e.preventDefault();touch[dir]=true};const off=e=>{e.preventDefault();touch[dir]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});
  const boostButton=document.getElementById('boostButton');boostButton.addEventListener('pointerdown',e=>{e.preventDefault();touch.boost=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>boostButton.addEventListener(ev,e=>{e.preventDefault();touch.boost=false}));
  document.getElementById('soundButton').addEventListener('click',()=>{soundOn=!soundOn;document.querySelector('#soundButton span').textContent=soundOn?'ON':'SOUND';if(soundOn){audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume()}});
  function tone(freq=440,duration=.08,type='sine',volume=.035){if(!soundOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
  function input(){return {x:(keys.has('arrowright')||keys.has('d')||touch.right?1:0)-(keys.has('arrowleft')||keys.has('a')||touch.left?1:0),y:(keys.has('arrowdown')||keys.has('s')||touch.down?1:0)-(keys.has('arrowup')||keys.has('w')||touch.up?1:0),boost:keys.has(' ')||keys.has('space')||touch.boost}}
  function update(dt){time+=dt*1000;if(mode!=='playing')return;runTime+=dt;
    const inp=input();const accel=3.0;player.vx+=(inp.x*accel-player.vx*3.1)*dt;player.vy+=(inp.y*accel-player.vy*3.1)*dt;player.x=clamp(player.x+player.vx*dt,-.86,.86);player.y=clamp(player.y+player.vy*dt,-.59,.66);player.tilt+=(inp.x*.45-player.tilt)*Math.min(1,dt*6);
    const wind=current(),onWake=Math.hypot(player.x-wind.x,player.y-wind.y)<.22;
    if(onWake){charge=clamp(charge+dt*34,0,100);if(charge===100&&wakeState.textContent!=='BURST READY')notify('WAKE CHARGED — RELEASE A BURST')}
    else charge=clamp(charge-dt*13,0,100);
    if(inp.boost&&charge>=100&&burst<=0){charge=0;burst=2.15;tone(190,.32,'sawtooth',.06);notify('WAKE BURST!')}
    if(burst>0)burst=Math.max(0,burst-dt);
    wakeFill.style.width=charge+'%';wakeState.textContent=burst>0?'BURST ACTIVE':charge>=100?'BURST READY':onWake?'RIDING THE CURRENT':'FIND THE CURRENT';
    const speed=(burst>0?9.8:6.5);const travel=speed*dt;
    for(const o of objects){if(o.done)continue;o.z-=travel;
      if(o.type==='gate'&&o.z<=.22){o.done=true;const d=Math.hypot(player.x-o.x,player.y-o.y);if(d<.48){score++;streak++;bestStreak=Math.max(streak,bestStreak);gateCount.textContent=String(score).padStart(2,'0');tone(490+score*38,.13,'triangle');notify(['CLEAN LINE','GATE CLEARED','NICE FLIGHT'][score%3]);if(score>=8){end(true);break}}else{misses++;streak=0;shake=12;tone(95,.25,'sawtooth',.06);notify('GATE MISSED · '+(3-misses)+' LIVES LEFT');if(misses>=3){end(false);break}}}
      if(o.type==='shard'&&o.z<=.28){o.done=true;if(Math.hypot(player.x-o.x,player.y-o.y)<.3){shards++;shardCount.textContent=shards;tone(750,.18,'sine');notify('SUN SHARD '+shards+' / 5')} }
      if(o.type==='mine'&&o.z<=.25){o.done=true;if(Math.hypot(player.x-o.x,player.y-o.y)<.25){misses++;streak=0;shake=15;tone(78,.35,'sawtooth',.07);notify('STORM MINE · '+(3-misses)+' LIVES LEFT');if(misses>=3){end(false);break}}}
    }
    if(burst>0&&Math.random()<.7)particles.push({x:player.x+rand(-.04,.04),y:player.y+rand(-.05,.05),life:.4,max:.4});
    for(const p of particles)p.life-=dt;particles=particles.filter(p=>p.life>0);objects=objects.filter(o=>!o.done&&o.z>-2);if(shake>0)shake=Math.max(0,shake-dt*26);
  }
  function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
  function poly(points,color){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=color;ctx.fill()}
  function background(){
    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#142d43');sky.addColorStop(.38,'#416777');sky.addColorStop(.66,'#b1aa91');sky.addColorStop(1,'#425c5e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    const sunX=W*.73,sunY=H*.25,sunR=Math.min(W,H)*.09;let glow=ctx.createRadialGradient(sunX,sunY,2,sunX,sunY,sunR*2.7);glow.addColorStop(0,'rgba(255,230,175,.75)');glow.addColorStop(.22,'rgba(255,211,154,.28)');glow.addColorStop(1,'rgba(255,208,156,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-sunR*3,sunY-sunR*3,sunR*6,sunR*6);ctx.beginPath();ctx.arc(sunX,sunY,sunR*.46,0,Math.PI*2);ctx.fillStyle='rgba(255,232,189,.75)';ctx.fill();
    // Distant layered mesas and drifting cloud banks.
    const horizon=H*.48;for(let layer=0;layer<3;layer++){const y=horizon+layer*H*.047;ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,y+20);for(let x=0;x<=W+40;x+=40){const peak=Math.sin(x*.006+layer*2.4)*14+Math.sin(x*.017+layer)*7;ctx.lineTo(x,y+peak+Math.sin(x*.0014+layer)*17)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['rgba(33,62,70,.36)','rgba(26,52,61,.42)','rgba(13,38,48,.5)'][layer];ctx.fill()}
    // Long cloud streaks.
    for(let i=0;i<8;i++){const yy=H*(.25+i*.045)+Math.sin(time*.00016+i)*5;const xx=((i*203-time*(.006+i*.0008))%(W+300)+W+300)%(W+300)-150;ctx.fillStyle=`rgba(234,231,207,${.055+(i%3)*.016})`;ctx.beginPath();ctx.ellipse(xx,yy,90+i%3*45,4+i%2*3,-.03,0,Math.PI*2);ctx.fill()}
    // Perspective wind-road rails.
    const vanishX=W*.5,vanishY=horizon+H*.025;for(let i=-5;i<=5;i++){const bx=W*.5+i*W*.105;line(vanishX+((bx-W*.5)*.045),vanishY,bx,H*1.03,i===0?'rgba(181,226,204,.16)':'rgba(172,216,198,.085)',i===0?1.2:1)}
    for(let i=1;i<9;i++){let p=((i*.13+time*.00015)%1);let yy=vanishY+(H-vanishY)*p*p;line(W*.12,yy,W*.88,yy,`rgba(201,235,211,${.035+p*.055})`,1)}
    // Moving current stream, curving into the horizon.
    ctx.save();ctx.globalCompositeOperation='screen';for(let side=-1;side<=1;side+=2){ctx.beginPath();for(let j=0;j<=32;j++){const z=23*(j/32),w=current(),curve=Math.sin(time*.00025+z*.18)*.06;const x=w.x+curve+side*(.08+z*.008),y=w.y+Math.cos(time*.00021+z*.2)*.025;const sc=1/(1+z*.075);const px=W*.5+x*W*.36*sc,py=vanishY+(y*H*.28)*sc+(H*.30)*(1-sc);if(j===0)ctx.moveTo(px,py);else ctx.lineTo(px,py)}ctx.strokeStyle=side<0?'rgba(86,246,225,.2)':'rgba(105,246,226,.33)';ctx.lineWidth=side<0?2:1.5;ctx.shadowColor='#69f6e2';ctx.shadowBlur=15;ctx.stroke()}ctx.restore();
